const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const G=require('./dist/engine.js');const legacyFixture=require('./fixtures/legacy-saves.json');const legacy=name=>JSON.parse(JSON.stringify(legacyFixture[name]));let checks=0;const results=[];
function check(name,fn){try{fn();checks++;results.push(name);}catch(e){console.error('FAILED: '+name);throw e;}}
function start(preset='lean',seed=7,free=false,size=4){const s=G.fresh(seed,free,size,preset);G.settleUpkeep(s);G.finishUpkeep(s);return s;}
function team(s,n=4){return G.localMercs(s).filter(G.available).slice(0,n).map(m=>m.id);}
function leads(s,c,ids){return G.chooseLeads(s,c,ids);}
function settleEvent(s){while(G.nextJob(s)){if(s.operations.pendingReview)G.acknowledgePhase(s);else G.rollPhase(s);}if(s.operations.pendingReview)G.acknowledgePhase(s);for(const c of [...s.operations.choices])G.choice(s,c.id,c.type==='failedPay'?(s.cash>=G.round(s.jobs.find(j=>j.id===c.job).quote.pay*.5)?'half':'none'):'none');G.finishOperations(s);}
function boundary(s){G.endActivity(s);settleEvent(s);G.respondEvent(s,'pass');G.advance(s);}
function open(s){G.settleUpkeep(s);for(const c of [...s.upkeep.choices])G.choice(s,c.id,'stop');G.finishUpkeep(s);}
function next(s){boundary(s);open(s);}
function mission(s,outcome=null){const c=s.board.find(c=>c.status==='Offer'&&c.baseId===s.operatingBase),ids=team(s);G.secure(s,c.id,'command');const j=G.deploy(s,c.id,ids,leads(s,c,ids));if(outcome!==null)j.rolls=j.quote.checks.map(r=>({...r,face:outcome?20:1,degree:outcome?3:0,actualModifier:r.modifier}));return j;}
function snapshot(s){return JSON.stringify(s);}
check('fresh staffed game starts with an unpaid current-interval invoice',()=>{const s=G.fresh(0);assert.equal(s.seed,0);assert.equal(s.rules,'0.3.10');assert.equal(s.phase,'upkeep');assert.equal(s.cash,2000);assert.equal(s.actions,0);assert.equal(s.upkeep.invoice.reduce((n,l)=>n+l.amount,0),350);assert.equal(G.forecast(s),365);assert.throws(()=>G.finishUpkeep(s));});
check('settlement and individual payment are idempotent',()=>{const s=G.fresh();const l=s.upkeep.invoice[0];G.payInvoiceLine(s,l.id);assert.equal(s.cash,1700);const before=snapshot(s);assert.throws(()=>G.payInvoiceLine(s,l.id));assert.equal(snapshot(s),before);G.settleUpkeep(s);assert.equal(s.cash,1650);assert.throws(()=>G.settleUpkeep(s));G.finishUpkeep(s);assert.equal(s.actions,4);assert.equal(s.ledger.reduce((n,l)=>n+l.amount,2000),s.cash);});
check('lean and expansion presets have explicit money, level and first bills',()=>{const l=G.fresh(7,false,4,'lean');assert.equal(l.facilities.length,0);assert.equal(l.upkeep.invoice[0].amount,300);const s=start('expansion');assert.equal(s.cash,7700);assert.equal(s.initialCash,8000);assert.equal(s.guildLevel,4);assert.equal(s.actions,7);assert(s.mercs.every(m=>m.level===3));assert(s.board.every(c=>c.level===3));});
check('second staffed invoice includes prior asset upkeep once',()=>{const s=start('staffed');assert.equal(s.cash,1650);boundary(s);assert.equal(s.cash,1650);assert.equal(s.upkeep.invoice.reduce((n,l)=>n+l.amount,0),365);G.prepareUpkeep(s);assert.equal(s.upkeep.invoice.length,3);open(s);assert.equal(s.cash,1285);});
check('pause service ends monthly renewal but preserves accrued maintenance',()=>{const s=start('staffed');boundary(s);const f=s.facilities[0];G.renewStaff(s,f.id,false);assert.equal(s.upkeep.invoice.reduce((n,l)=>n+l.amount,0),315);assert(!G.facilityOperational(s,f));G.settleUpkeep(s);assert.equal(s.cash,1335);assert.equal(G.trainingCapacity(s),4);assert.throws(()=>G.renewStaff(s,f.id,true));});
check('already paid service cannot be cancelled retroactively',()=>{const s=G.fresh(),line=s.upkeep.invoice.find(l=>l.type==='staff');G.payInvoiceLine(s,line.id);const before=snapshot(s);assert.throws(()=>G.renewStaff(s,line.reference,false));assert.equal(snapshot(s),before);});
check('shortfall preserves per-obligation arrears and denies unfunded service',()=>{const s=G.fresh();s.cash=300;G.settleUpkeep(s);assert.equal(s.cash,0);assert.equal(s.arrears.reduce((n,a)=>n+a.amount,0),50);assert(!G.facilityOperational(s,s.facilities[0]));assert.equal(s.mercs[0].loyalty,50);G.finishUpkeep(s);s.cash=50;G.payArrears(s);assert.equal(s.arrears.length,0);assert(G.facilityOperational(s,s.facilities[0]));});
check('pay a selected bill first and retain all other shortfalls',()=>{const s=G.fresh();s.cash=50;G.payInvoiceLine(s,s.upkeep.invoice.find(l=>l.type==='staff').id);G.settleUpkeep(s);assert.equal(s.arrears.reduce((n,a)=>n+a.amount,0),300);assert.equal(s.cash,0);assert(G.facilityOperational(s,s.facilities[0]));});
check('facility project reserves local slots and charges manager once',()=>{const s=start('developing');G.project(s,'training_suite','quarter');assert.equal(s.cash,1100);assert.equal(G.locationSlots(s,'hq').reserved,1);assert.throws(()=>G.project(s,'training_suite','quarter'));boundary(s);assert.equal(s.facilities.length,1);assert.equal(s.upkeep.invoice.filter(l=>l.type==='asset').length,0);assert.equal(s.upkeep.invoice.reduce((n,l)=>n+l.amount,0),350);open(s);assert.equal(s.cash,750);assert.equal(G.trainingCapacity(s),6);next(s);assert.equal(s.cash,385);assert.equal(s.actionHistory.filter(h=>h.action.startsWith('Commission')).length,1);});
check('per-base slots and shared project capacity cannot be bypassed',()=>{const s=start('expansion');G.project(s,'training_suite','quarter');G.project(s,'recruitment_office','quarter');assert.equal(G.locationSlots(s,'hq').free,0);assert.throws(()=>G.project(s,'infirmary','quarter'));assert.equal(s.projects.length,2);});
check('all four expansion quotes separate construction, manager and payroll',()=>{assert.deepEqual(['training_suite','infirmary','recruitment_office','comms_hub'].map(t=>G.facilityQuote(t).cost),[600,1400,500,1700]);assert.deepEqual(['training_suite','infirmary','recruitment_office','comms_hub'].map(t=>G.facilityQuote(t).overhead),[65,90,35,75]);});
check('funded instructor replaces trainer fee but not materials',()=>{const s=start('staffed'),ids=team(s);assert.equal(G.trainingCost(s,ids),100);G.train(s,ids,'quarter');assert.equal(s.cash,1550);boundary(s);assert(s.mercs.every(m=>m.xp===150));G.settleUpkeep(s);const c=s.upkeep.choices[0];G.choice(s,c.id,'continue');assert.equal(s.cash,1085);assert.equal(s.cohorts[0].block,2);G.finishUpkeep(s);boundary(s);assert(s.mercs.every(m=>m.xp===315));open(s);assert(s.mercs.every(G.available));});
check('service pause after delivered training preserves XP and fallback trainer cost',()=>{const s=start('staffed');G.train(s,team(s),'quarter');boundary(s);assert(s.mercs.every(m=>m.xp===150));G.renewStaff(s,s.facilities[0].id,false);G.settleUpkeep(s);assert.equal(G.trainingCost(s,team(s),s.facilities[0].id),50);G.choice(s,s.upkeep.choices[0].id,'stop');assert(s.mercs.every(G.available));});
check('suite does not supply unlimited simultaneous cohorts',()=>{const s=start('staffed');for(let i=0;i<4;i++)s.mercs.push({...s.mercs[0],id:'extra'+i});const first=team(s,4);G.train(s,first,'quarter');const remaining=team(s,4);assert.equal(G.trainingCost(s,remaining),150);G.train(s,remaining,'quarter');assert.equal(s.cohorts.filter(c=>c.facilityId).reduce((n,c)=>n+c.ids.length,0),4);});
check('turnkey HQ purchase pays only the listed price and one action',()=>{const s=start('expansion'),before=s.cash,pool=s.actions;const b=G.purchaseBase(s,'permanent_hq','command');assert.equal(s.cash,before-6000);assert.equal(s.actions,pool-1);assert.equal(s.projects.length,0);assert.equal(b.status,'Pending');assert.equal(G.forecast(s),400);assert.throws(()=>G.focusBase(s,b.id));boundary(s);assert.equal(b.status,'Operational');assert.equal(s.upkeep.invoice.reduce((n,l)=>n+l.amount,0),400);assert.equal(s.pendingGuildXP,0);});
check('unaffordable purchase cannot spend cash or actions',()=>{const s=start();const before=snapshot(s);assert.throws(()=>G.purchaseBase(s,'permanent_hq','command'));assert.equal(snapshot(s),before);});
check('outpost purchase does not grant staffing or actions',()=>{const s=start('expansion');const b=G.purchaseBase(s,'outpost','command');boundary(s);G.settleUpkeep(s);G.finishUpkeep(s);assert(!G.baseOperational(s,b));assert.equal(G.actionPool(s),7);G.focusBase(s,b.id);assert.throws(()=>G.network(s,'command'));});
check('chief hiring, onboarding and pay enable local actions from shared pool',()=>{const s=start('expansion'),b=G.purchaseBase(s,'outpost','command');G.appointChief(s,b.id,'command');assert.equal(s.cash,4600);assert.equal(s.actions,5);boundary(s);assert(!G.baseOperational(s,b));assert.equal(s.upkeep.invoice.reduce((n,l)=>n+l.amount,0),505);open(s);assert(G.baseOperational(s,b));assert.equal(s.pendingGuildXP,80);G.focusBase(s,b.id);assert.throws(()=>G.network(s,'command'));G.network(s,b.chief.id,'contracts');assert.equal(s.actions,6);assert.equal(s.officers.length,5);assert.equal(G.actionPool(s),7);});
check('facility uniqueness is local and remote effects do not leak',()=>{const s=start('expansion'),b=G.purchaseBase(s,'outpost','command');G.appointChief(s,b.id,'command');G.project(s,'training_suite','quarter');next(s);G.focusBase(s,b.id);assert.equal(G.trainingCapacity(s),4);G.project(s,'training_suite',b.chief.id);assert.equal(s.projects.filter(p=>p.type==='training_suite').length,2);});
check('funded comms permits remote administrative leadership, no extra checks or actions',()=>{const s=start('expansion'),b=G.purchaseBase(s,'outpost','command');G.appointChief(s,b.id,'command');G.project(s,'comms_hub','quarter');next(s);next(s);G.focusBase(s,b.id);const pool=s.actions;G.network(s,'command','contracts');assert.equal(s.actions,pool-1);assert.equal(G.actionPool(s),7);});
check('crew transfer has real timing and does not teleport',()=>{const s=start('expansion'),b=G.purchaseBase(s,'outpost','command');G.appointChief(s,b.id,'command');next(s);const ids=team(s,2);G.transferCrew(s,ids,b.id,'command');assert(ids.every(i=>G.merc(s,i).status==='In Transit'));G.focusBase(s,b.id);assert.equal(team(s).length,0);next(s);assert(ids.every(i=>G.merc(s,i).status==='Available'&&G.merc(s,i).baseId===b.id));});
check('headquarters relocation retains old paid lease and ends it at notice boundary',()=>{const s=start('expansion'),b=G.purchaseBase(s,'field_hq','command');next(s);G.relocate(s,b.id,'command');assert.equal(s.primaryBase,b.id);assert.equal(s.cash,4225);assert.equal(G.base(s,'hq').endsAt,3);assert(s.mercs.every(m=>m.status==='In Transit'));boundary(s);assert.equal(G.base(s,'hq').status,'Closed');assert.equal(s.upkeep.invoice.reduce((n,l)=>n+l.amount,0),75);open(s);assert(s.mercs.every(G.available));});
check('owned installation transfer reserves target slot and provides no transit benefit',()=>{const s=start('expansion');G.project(s,'training_suite','quarter');const b=G.purchaseBase(s,'field_hq','command');next(s);const f=s.facilities[0];G.relocate(s,b.id,'command');assert(f.transfer);assert(!G.facilityOperational(s,f));assert.equal(G.locationSlots(s,b.id).reserved,1);boundary(s);assert.equal(f.baseId,b.id);assert(!f.transfer);assert(s.upkeep.invoice.some(l=>l.type==='staff'));open(s);assert(G.facilityOperational(s,f));});
check('landlord fixture cannot be moved, sold or billed forever after lease ends',()=>{const s=start('staffed');s.cash=8000;s.initialCash=8350;s.guildLevel=4;const b=G.purchaseBase(s,'field_hq','command');next(s);const f=s.facilities[0];G.relocate(s,b.id,'command');assert(!f.transfer);assert(!f.staff.active);boundary(s);assert.equal(f.returnedAt,s.turn);open(s);boundary(s);assert(!s.upkeep.invoice.some(l=>l.reference===f.id));});
check('retained recruitment gate and first payroll begin at onboarding completion',()=>{const s=start('expansion');s.mercs.push({...s.mercs[0],id:'candidate',status:'Candidate',expires:2});s.reputation=0;let before=snapshot(s);assert.throws(()=>G.hire(s,'candidate','command','retained'));assert.equal(snapshot(s),before);s.reputation=20;G.hire(s,'candidate','command','retained');const m=G.merc(s,'candidate');assert.equal(m.status,'Onboarding');assert.equal(G.retainer(m),85);assert.equal(G.assignmentWage(m),140);boundary(s);assert.equal(m.status,'Available');assert(s.upkeep.invoice.some(l=>l.reference===m.id&&l.type==='retainer'));open(s);assert.equal(m.retainerPaidTurn,2);});
check('unpaid retainer denies work without erasing agreement or changing Loyalty',()=>{const s=start();const m=s.mercs[0];m.employment='retained';m.retainerPaidTurn=1;boundary(s);const loyalty=m.loyalty;s.cash=300;G.settleUpkeep(s);G.finishUpkeep(s);assert.equal(m.employment,'retained');assert.equal(m.loyalty,loyalty);assert.throws(()=>G.quote(s,s.board[0],team(s),leads(s,s.board[0],team(s))));s.cash=55;G.payArrears(s);assert.equal(m.retainerPaidTurn,2);G.quote(s,s.board[0],team(s),leads(s,s.board[0],team(s)));});
check('frozen assignment wages survive level and employment changes after departure',()=>{const s=start();const j=mission(s);const amount=j.quote.pay;s.mercs[0].employment='retained';s.mercs[0].level=10;assert.equal(j.quote.pay,amount);assert.equal(j.quote.wageQuotes[0].wage,110);});
check('floor-average level, undersize DC and capped oversize circumstance remain',()=>{const s=start(),c=s.board[0];for(let i=0;i<2;i++)s.mercs.push({...s.mercs[0],id:'oversize'+i});const ids=team(s,6),q=G.quote(s,c,ids,leads(s,c,ids));assert.equal(q.payout,720);assert.equal(q.sizeBonus,2);assert(q.checks.every(c=>c.dc===15&&c.circumstance===2));c.preparation={phase:1,bonus:2,expires:2};assert.equal(G.quote(s,c,ids,leads(s,c,ids)).checks[1].circumstance,2);const small=ids.slice(0,3);assert(G.quote(s,c,small,leads(s,c,small)).checks.every(c=>c.dc===16));});
check('exactly three mission rolls and no rerolls across saved partial results',()=>{const s=start(),j=mission(s);G.endActivity(s);G.rollPhase(s);const first=snapshot(j.rolls[0]),reload=JSON.parse(snapshot(s));G.acknowledgePhase(s);G.rollPhase(s);G.acknowledgePhase(s);G.rollPhase(s);G.acknowledgePhase(reload);G.rollPhase(reload);G.acknowledgePhase(reload);G.rollPhase(reload);assert.equal(snapshot(j.rolls[0]),first);assert.deepEqual(reload.jobs[0].rolls,j.rolls);assert.throws(()=>G.rollPhase(s));});
check('Events success receipts precede wages and XP settles at advancement',()=>{const s=start(),j=mission(s,true);s.cash=0;s.ledger=[];s.guildXP=920;G.endActivity(s);assert.equal(s.cash,460);assert.equal(s.ledger[0].category,'client');assert.equal(s.pendingGuildXP,80);assert(s.mercs.every(m=>m.xp===250));assert.equal(s.guildLevel,1);settleEvent(s);G.respondEvent(s,'pass');assert.equal(s.guildLevel,2);assert.equal(s.featChoices,0);G.advance(s);open(s);assert.equal(s.actions,5);});
check('failed full/half/no wages change Loyalty +5/0/-5 without rep offset',()=>{for(const [v,d,cost] of [['full',5,440],['half',0,220],['none',-5,0]]){const s=start();mission(s,false);G.endActivity(s);const cash=s.cash,loyalty=s.mercs.map(m=>m.loyalty);G.choice(s,s.operations.choices[0].id,v);assert.equal(s.cash,cash-cost);assert.deepEqual(s.mercs.map(m=>m.loyalty),loyalty.map(x=>x+d));assert.equal(s.reputation,-3);assert(s.mercs.every(m=>m.xp===100));}});
check('unfunded failure pay cannot create cash or Loyalty',()=>{const s=start();mission(s,false);G.endActivity(s);s.cash=0;const before=snapshot(s);assert.throws(()=>G.choice(s,s.operations.choices[0].id,'full'));assert.equal(snapshot(s),before);});
check('mandatory recovery occupies next interval and releases following boundary',()=>{const s=start();s.board[0].kind='exclusive';const j=mission(s,true);next(s);assert.equal(j.result.recovery,1);assert(s.mercs.every(m=>m.status==='Recovering'&&m.readyAt===3));next(s);assert(s.mercs.every(G.available));});
check('funded local infirmary preserves mandatory floor and cannot serve other bases',()=>{const s=start('expansion');G.project(s,'infirmary','quarter');next(s);next(s);s.board.push({...s.board[0],id:'demand',status:'Offer',kind:'exclusive',expires:9});const c=s.board.find(c=>c.id==='demand'),ids=team(s);G.secure(s,c.id,'command');const j=G.deploy(s,c.id,ids,leads(s,c,ids));j.rolls=j.quote.checks.map(r=>({...r,face:20,degree:3,actualModifier:r.modifier}));G.endActivity(s);assert.equal(j.result.recovery,1);});
check('exclusive breach penalizes rep while ordinary expiry does not',()=>{const s=start();s.board[0].kind='exclusive';G.secure(s,s.board[0].id,'command');next(s);assert.equal(s.reputation,-4);assert(s.mercs.every(m=>m.xp===0));const normal=start();G.secure(normal,normal.board[0].id,'command');next(normal);next(normal);assert.equal(normal.reputation,0);});
check('every PC has first-action capacity; no officer cap across party sizes',()=>{for(let n=1;n<=8;n++){const s=start('lean',7,false,n);assert.equal(s.actions,n);assert.equal(s.officers.length,n);s.cash=5000;for(const o of s.officers)G.network(s,o.id,'contracts');assert.equal(s.actions,0);}const s=start();for(let i=0;i<4;i++)G.network(s,'command','contracts');assert.equal(s.officers[0].used,4);assert.throws(()=>G.network(s,'command'));});
check('free acquisition variant preserves the shared pool',()=>{const s=start('lean',7,true),pool=s.actions;G.secure(s,s.board[0].id,'command');assert.equal(s.actions,pool);});
check('recruitment office upgrades quality on success+, maintains count3 and no free hire',()=>{let observed=false;for(let seed=0;seed<40;seed++){const s=start('expansion',seed);G.project(s,'recruitment_office','quarter');next(s);const before=s.actions,count=G.network(s,'command','recruits');const d=s.lastRoll.degree;assert.equal(count,d===0?(s.lastDiscovery.countRoll<=10?0:1):3);if(d>=2&&s.lastDiscovery.results.some(x=>x.notes.includes('Recruitment Office specialist')))assert(s.lastDiscovery.results.some(x=>x.rarity!=='Common'));assert.equal(s.actions,before-1);assert(s.mercs.filter(m=>m.status==='Candidate').every(m=>m.readyAt===undefined));if(d===2){observed=true;break;}}assert(observed);});
check('migration retains old cash, invoices, rolls, quotes and outcomes',()=>{const s=legacy('partialEvent'),j=s.jobs[0];const cash=s.cash,quote=snapshot(j.quote),roll=snapshot(j.rolls);G.migrate(s);assert.equal(s.cash,cash);assert.equal(snapshot(j.quote),quote);assert.equal(snapshot(j.rolls),roll);assert.equal(s.facilities.length,0);assert.equal(s.rules,'0.3.10');assert.equal(G.base(s,'hq').monthly,300);});
check('already settled 0.3.3 Upkeep is not charged again',()=>{const s=legacy('settledUpkeep');const cash=s.cash,ledger=s.ledger.length;G.migrate(s);assert.equal(s.cash,cash);assert.equal(s.ledger.length,ledger);assert.equal(s.upkeep.invoice.length,0);G.finishUpkeep(s);assert.equal(s.cash,cash);});
check('reload does not repeat prepared completions or invoice settlement',()=>{const s=start('staffed');G.train(s,team(s),'quarter');boundary(s);const clone=JSON.parse(snapshot(s));G.migrate(clone);G.prepareUpkeep(clone);assert.equal(clone.mercs[0].xp,150);assert.equal(clone.upkeep.choices.length,1);G.settleUpkeep(clone);const cash=clone.cash;assert.throws(()=>G.settleUpkeep(clone));assert.equal(clone.cash,cash);});
check('older 0.3.1/0.3.2 partial mission and pool migration remain usable',()=>{for(const version of ['0.3.1','0.3.2']){const s=legacy('activeMission');s.rules=version;const cash=s.cash;G.migrate(s);assert.equal(s.cash,cash);G.endActivity(s);settleEvent(s);G.respondEvent(s,'pass');G.advance(s);open(s);assert.equal(s.turn,2);}});
check('48 campaigns ×6 intervals preserve cash and interval invariants',()=>{for(let seed=0;seed<48;seed++){const s=start(seed%3===0?'staffed':'lean',seed,seed%2===0);for(let t=0;t<6;t++){const ids=team(s),c=s.board.find(c=>c.status==='Offer'&&c.kind==='standard'&&c.baseId===s.operatingBase);if(ids.length>=3&&c&&leads(s,c,ids)){G.secure(s,c.id,'command');G.deploy(s,c.id,ids,leads(s,c,ids));}if(s.actions)G.network(s,'command','contracts');next(s);assert.equal(s.cash,s.initialCash+s.ledger.reduce((n,l)=>n+l.amount,0));assert(s.cash>=0);assert(s.actions>=0&&s.actions<=G.actionPool(s));assert(s.mercs.every(m=>m.level>=1&&m.level<=20));assert.equal(new Set(s.upkeep.invoice.map(l=>l.id)).size,s.upkeep.invoice.length);}}});
check('UI smoke covers invoices, purchases, renewal, locations and reset settings',()=>{const elements={},handlers={};function el(id){return elements[id]||(elements[id]={id,innerHTML:'',textContent:'',value:'',open:false,className:'',classList:{toggle(){}},addEventListener(){},showModal(){this.open=true},close(){this.open=false}});}const doc={getElementById:el,querySelector(){return el('query')},querySelectorAll(){return []},addEventListener(t,fn){handlers[t]=fn}};const sandbox={window:{GuildGame:G},document:doc,localStorage:{getItem(){return null},setItem(){}},navigator:{},setTimeout,console};vm.createContext(sandbox);vm.runInContext(fs.readFileSync('./dist/app.js','utf8'),sandbox);function click(dataset){handlers.click({target:{closest:()=>({dataset,disabled:false})}});}assert(el('stage-panel').innerHTML.includes('350'));assert(el('stage-panel').innerHTML.includes('Training Instructor'));assert(el('workspace').innerHTML.includes('Mobile Field HQ'));for(const tab of ['contracts','people','log','development'])click({tab});click({do:'settle-upkeep'});assert(el('stage-panel').innerHTML.includes('Payments recorded'));click({do:'finish-upkeep'});assert.equal(sandbox.window.GuildPlaytest.getState().cash,1650);click({do:'settings'});assert(el('modal-content').innerHTML.includes('Expansion test'));el('preset').value='expansion';el('party-size').value='4';el('seed').value='7';el('acquisition').value='paid';click({do:'reset-confirm'});assert.equal(sandbox.window.GuildPlaytest.getState().cash,8000);click({do:'settle-upkeep'});click({do:'finish-upkeep'});click({do:'buy-base',type:'outpost'});assert(el('modal-content').innerHTML.includes('3,000'));click({do:'buy-base-confirm',type:'outpost'});const b=sandbox.window.GuildPlaytest.getState().bases[1];click({do:'chief',id:b.id});click({do:'end-confirm'});click({do:'finish-operations'});click({do:'event-pass'});click({do:'advance'});assert(el('stage-panel').innerHTML.includes('Outpost Chief'));click({do:'settle-upkeep'});click({do:'finish-upkeep'});handlers.change({target:{id:'operating-base',value:b.id,matches(){return false}}});assert(el('workspace').innerHTML.includes('regional')||el('workspace').innerHTML.includes('Regional'));});
check('five contract bands use the published level table and selected adjustments',()=>{const expected=[null,15,16,18,19,20,22,23,24,26,27,28,30,31,32,34,35,36,38,39,40];assert.deepEqual(G.V.level_dc,expected);for(const [kind,dc,n] of [['routine',-2,1],['standard',0,2],['demanding',2,2],['expert',5,2],['legendary',5,3]]){assert.equal(G.V.contracts[kind].dc_offset,dc);assert.equal(G.V.contracts[kind].required_successes,n);}assert.equal(G.V.contracts.exclusive.required_successes,2);assert.equal(G.V.contracts.exclusive.label,'Hard');});
check('new quote rejects duplicate phase leads and squads under three without mutation',()=>{const s=start(),c=s.board[0],ids=team(s),before=snapshot(s);assert.throws(()=>G.quote(s,c,ids,[ids[0],ids[0],ids[0]]));assert.throws(()=>G.quote(s,c,ids.slice(0,2),[ids[0],ids[1],ids[0]]));assert.equal(snapshot(s),before);const chosen=G.chooseLeads(s,c,ids);assert.equal(new Set(chosen).size,3);assert.equal(G.quote(s,c,ids,chosen).checks.length,3);});
check('phase skill requirements use actual rank and do not conflate tier names',()=>{const s=start(),c=s.board[0],ids=team(s),chosen=leads(s,c,ids);c.minimumLeadRanks=['Expert','Trained','Trained'];assert.throws(()=>G.quote(s,c,ids,chosen));s.mercs.forEach(m=>m.level=5);assert(G.quote(s,c,ids,chosen));c.kind='legendary';delete c.minimumLeadRanks;s.mercs.forEach(m=>m.level=1);assert(G.quote(s,c,ids,chosen));});
check('each phase holds its result until acknowledgement, including the final roll',()=>{const s=start(),j=mission(s);G.endActivity(s);for(let p=0;p<3;p++){G.rollPhase(s);assert.equal(j.rolls.length,p+1);assert.equal(s.operations.pendingReview.phase,p);const before=snapshot(s);assert.throws(()=>G.rollPhase(s));assert.equal(snapshot(s),before);assert(!s.operations.settled);if(p<2)G.acknowledgePhase(s);}assert(!j.settled);G.acknowledgePhase(s);assert(j.settled);assert.equal(j.rolls.length,3);assert.throws(()=>G.acknowledgePhase(s));});
check('two successes complete Hard and Expert but not Legendary',()=>{for(const kind of ['demanding','expert','legendary']){const s=start();s.board[0].kind=kind;const j=mission(s);j.rolls=j.quote.checks.map((r,p)=>({...r,face:p===0?5:20,degree:p===0?1:3,actualModifier:r.modifier}));G.endActivity(s);assert.equal(j.result.success,kind!=='legendary');assert(j.result.complications.some(c=>c.type==='injury'));}});
check('Easy and Normal complications trigger only on critical failure',()=>{for(const kind of ['routine','standard']){const s=start();s.board[0].kind=kind;const j=mission(s);assert.equal(G.phaseComplication(s,j,1,1),null);assert.equal(G.phaseComplication(s,j,1,0).type,'repairs');assert.equal(G.phaseComplication(s,j,2,0).type,'missing');assert.equal(G.phaseComplication(s,j,0,0).recovery,1);}});
check('risky-tier failed phases cause visible bills, recovery and a missing operative',()=>{const s=start();s.board[0].kind='demanding';const j=mission(s);j.rolls=j.quote.checks.map(r=>({...r,face:5,degree:1,actualModifier:r.modifier}));const cash=s.cash;G.endActivity(s);assert.equal(j.result.complications.length,3);assert.equal(s.cash,cash-110);assert.equal(G.merc(s,j.leads[0]).status,'Recovering');assert.equal(G.merc(s,j.leads[2]).status,'Missing');assert(j.result.complications.every(c=>c.text));assert.equal(s.ledger.filter(l=>l.category==='repairs').length,1);});
check('Legendary consequences exceed Expert at matching DC and trigger degree',()=>{const a=start(),b=start();a.board[0].kind='expert';b.board[0].kind='legendary';const ja=mission(a),jb=mission(b);assert.equal(ja.quote.checks[0].dc,jb.quote.checks[0].dc);assert(G.phaseComplication(b,jb,1,1).amount>G.phaseComplication(a,ja,1,1).amount);assert(G.phaseComplication(b,jb,0,1).recovery>G.phaseComplication(a,ja,0,1).recovery);});
check('Expert and Legendary completion add a referral without free hiring',()=>{for(const kind of ['expert','legendary']){const s=start();s.board[0].kind=kind;const j=mission(s,true);G.endActivity(s);const referral=s.mercs.find(m=>m.status==='Candidate');assert(referral);assert.equal(referral.expires,2);assert.equal(referral.readyAt,undefined);assert(j.result.additionalReward.includes('Specialist referral'));if(kind==='legendary')assert(s.contacts.includes('Ghost Fleet Liaison'));}});
check('contract search rolls disclosed quality tables and records every administrative roll',()=>{const s=start();G.network(s,'command','contracts',1);assert.equal(s.board.slice(2).length,3);assert(s.lastDiscovery.results.every(x=>x.rolls.level>=1&&x.rolls.rarity<=20));assert.equal(s.rollHistory.length,1);assert.equal(s.lastRoll.total,s.lastRoll.face+s.lastRoll.modifier);G.promote(s,'command');assert.equal(s.rollHistory.length,2);assert(s.rollHistory.every(r=>r.degree>=0&&r.degree<=3));});
check('current deployed old Hard contract retains three successes and no new complication',()=>{const s=start(),j=mission(s);s.rules='0.3.4';j.contract.kind='demanding';delete j.quote.contractRules;const cash=s.cash,quote=snapshot(j.quote);G.migrate(s);assert.equal(snapshot(j.quote),quote);assert.equal(s.cash,cash);assert.equal(j.rulesSnapshot.required_successes,3);j.rolls=j.quote.checks.map((r,p)=>({...r,face:p===0?1:20,degree:p===0?0:3,actualModifier:r.modifier}));G.endActivity(s);assert.equal(j.result.success,false);assert.equal(j.result.complications.length,0);});
check('UI keeps administrative outcomes and third mission roll visible on screen',()=>{const elements={},handlers={};function el(id){return elements[id]||(elements[id]={id,innerHTML:'',textContent:'',value:'',open:false,classList:{toggle(){}},addEventListener(){},showModal(){this.open=true},close(){this.open=false}});}const document={getElementById:el,querySelector(){return el('query')},querySelectorAll(){return []},addEventListener(t,fn){handlers[t]=fn}};const s=start('lean'),j=mission(s),box={window:{GuildGame:G},document,localStorage:{getItem(){return snapshot(s)},setItem(){}},navigator:{},setTimeout,console};vm.createContext(box);vm.runInContext(fs.readFileSync('./dist/app.js','utf8'),box);function click(dataset){handlers.click({target:{closest:()=>({dataset,disabled:false})}});}click({do:'promote'});assert(el('roll-results').innerHTML.includes('Promote the Guild'));assert(el('roll-results').innerHTML.includes('d20'));assert(/Critical Failure|Failure|Success|Critical Success/.test(el('roll-results').innerHTML));click({do:'end-confirm'});click({do:'roll'});click({do:'roll-next'});click({do:'roll-next'});assert(el('stage-panel').innerHTML.includes('Extraction'));assert(el('stage-panel').innerHTML.includes('Review complete'));assert.equal(box.window.GuildPlaytest.getState().jobs[0].settled,false);click({do:'review-phase'});assert(el('stage-panel').innerHTML.includes('Extraction'));assert(el('stage-panel').innerHTML.includes('d20'));click({tab:'log'});assert(el('workspace').innerHTML.includes('Extraction'));});

function financed(){const s=start('developing');mission(s,true);next(s);return s;}
check('development gates reject early investments without mutation and preserve starting services',()=>{const s=start('staffed'),before=snapshot(s);assert.throws(()=>G.project(s,'recruitment_office','quarter'),/Level 2/);assert.throws(()=>G.purchaseBase(s,'field_hq','command'),/Level 4/);assert.throws(()=>G.borrow(s,'unsecured',100,'command'),/Level 2/);assert.equal(snapshot(s),before);assert(G.facilityOperational(s,s.facilities[0]));const d=start('developing');G.project(d,'recruitment_office','quarter');assert.equal(d.projects.length,1);assert.throws(()=>G.purchaseBase(d,'field_hq','command'),/Level 4/);});
check('odd levels earn feats and even levels expand development capacity',()=>{const s=start();for(let level=2;level<=10;level++){s.guildXP=1000;s.pendingGuildXP=0;s.phase='event';s.operations={complete:true};s.event={type:'lead'};G.respondEvent(s,'pass');assert.equal(s.guildLevel,level);assert.equal(s.featChoices,[3,5,7,9].filter(l=>l<=level).length);}assert.deepEqual(G.V.project_capacity.slice(4),[2,2,3,3,4,4,5]);assert.equal(G.guildFeats.find(f=>f.id==='trusted').level,3);});
check('old earned feat entitlement is retained without a duplicate at the next odd level',()=>{const s=start();s.rules='0.3.5';s.guildLevel=2;s.featChoices=1;const cash=s.cash;G.migrate(s);assert.equal(s.featChoices,1);assert.equal(s.legacyFeatCredit,1);s.guildXP=1000;G.endActivity(s);settleEvent(s);G.respondEvent(s,'pass');assert.equal(s.guildLevel,3);assert.equal(s.featChoices,1);assert.equal(s.legacyFeatCredit,0);assert.equal(s.cash,cash);const before=snapshot(s);G.migrate(s);assert.equal(snapshot(s),before);});
check('loan underwriting counts completed-turn client receipts and excludes financing/capital',()=>{const s=start('developing');assert.throws(()=>G.loanQuote(s,'unsecured',100),/recorded/);mission(s,true);next(s);assert.equal(G.averageRevenue(s),900);s.ledger.push({turn:1,amount:9000,category:'financing'},{turn:1,amount:9000,category:'capital'});assert.equal(G.averageRevenue(s),900);next(s);assert.equal(G.averageRevenue(s),450);});
check('loan disbursement spends one action and first payment is principal plus interest next Upkeep',()=>{const s=financed(),cash=s.cash,pool=s.actions,l=G.borrow(s,'unsecured',1200,'command');assert.equal(s.cash,cash+1200);assert.equal(s.actions,pool-1);assert.equal(s.ledger.at(-1).category,'financing');assert.equal(G.forecast(s),424);boundary(s);const line=s.upkeep.invoice.find(x=>x.type==='loan');assert.equal(line.loanPrincipal,100);assert.equal(line.loanInterest,24);const entering=s.cash;G.prepareUpkeep(s);assert.equal(s.cash,entering);G.payInvoiceLine(s,line.id);assert.equal(l.remaining,1100);assert.throws(()=>G.payInvoiceLine(s,line.id));open(s);assert.equal(l.status,'Current');assert.equal(G.loanDue(s,l).interest,22);assert.equal(s.cash,s.initialCash+s.ledger.reduce((n,x)=>n+x.amount,0));});
check('aggregate service limit, amount validation and arrears refusal happen before mutation',()=>{const s=financed();s.guildLevel=4;G.borrow(s,'unsecured',1200,'command');const before=snapshot(s);for(const n of [99,150,1600,4100])assert.throws(()=>G.borrow(s,'unsecured',n,'command'));assert.equal(snapshot(s),before);G.borrow(s,'unsecured',500,'command');assert.equal(s.loans.length,2);s.arrears.push({id:'x',amount:1});const again=snapshot(s);assert.throws(()=>G.borrow(s,'unsecured',100,'command'),/arrears/);assert.equal(snapshot(s),again);});
check('partial debt payment covers interest first and unpaid principal is not billed twice',()=>{const s=financed(),l=G.borrow(s,'unsecured',1200,'command');boundary(s);s.cash=30;const line=s.upkeep.invoice.find(x=>x.type==='loan');G.payInvoiceLine(s,line.id);assert.equal(l.remaining,1194);G.settleUpkeep(s);assert.equal(l.status,'Delinquent');const a=s.arrears.find(a=>a.service?.reference===l.id);assert.equal(a.amount,94);G.finishUpkeep(s);boundary(s);assert.equal(l.status,'Default');const current=s.upkeep.invoice.find(x=>x.type==='loan');assert.equal(current.loanPrincipal,100);assert.equal(current.loanInterest,24);s.cash=1000;const old=s.upkeep.invoice.find(x=>x.type==='arrears'&&x.reference===a.id);G.payInvoiceLine(s,old.id);assert.equal(l.remaining,1100);assert.equal(a.amount,0);G.settleUpkeep(s);assert.equal(l.remaining,1000);assert.equal(l.status,'Current');});
check('routine arrears cure updates principal and releases default without a new action',()=>{const s=financed(),l=G.borrow(s,'unsecured',1200,'command');boundary(s);s.cash=0;G.settleUpkeep(s);G.finishUpkeep(s);const pool=s.actions;s.cash=424;G.payArrears(s);assert.equal(l.remaining,1100);assert.equal(l.status,'Current');assert.equal(s.actions,pool);assert.equal(s.arrears.length,0);});
check('early principal repayment costs no action, lowers future interest and completes agreement',()=>{const s=financed(),l=G.borrow(s,'unsecured',1200,'command'),pool=s.actions;G.repayLoan(s,l.id,200);assert.equal(l.remaining,1000);assert.equal(G.loanDue(s,l).interest,20);assert.equal(s.actions,pool);G.repayLoan(s,l.id,1000);assert.equal(l.status,'Paid');assert.equal(G.loanDue(s,l).total,0);const before=snapshot(s);assert.throws(()=>G.repayLoan(s,l.id,1));assert.equal(snapshot(s),before);});
check('twelve payments retire principal exactly, reduce interest and retain conservation',()=>{const s=financed(),l=G.borrow(s,'unsecured',1000,'command');s.cash+=10000;s.ledger.push({turn:s.turn,amount:10000,note:'Test reserve',category:'capital'});for(let n=0;n<12;n++)next(s);assert.equal(l.remaining,0);assert.equal(l.status,'Paid');const lines=s.ledger.filter(x=>x.category==='loan');assert.equal(lines.length,12);assert.equal(lines[0].amount,-104);assert.equal(lines.at(-1).amount,-78);assert.equal(s.cash,s.initialCash+s.ledger.reduce((n,x)=>n+x.amount,0));assert.equal(G.forecast(s),300);});
check('secured finance requires level four, operational owned collateral and a unique pledge',()=>{const s=start('expansion');const b=G.purchaseBase(s,'field_hq','command');assert.throws(()=>G.loanQuote(s,'secured',100,b.id),/operational/);mission(s,true);next(s);const cash=s.cash,pool=s.actions;const l=G.borrow(s,'secured',2000,'command',b.id);assert.equal(l.rate,.01);assert.equal(l.collateral,b.id);assert.equal(s.cash,cash+2000);assert.equal(s.actions,pool-1);const before=snapshot(s);assert.throws(()=>G.borrow(s,'secured',100,'command',b.id),/already pledged/);assert.throws(()=>G.borrow(s,'secured',100,'command','hq'),/leases/);assert.equal(snapshot(s),before);G.repayLoan(s,l.id,2000);assert(G.loanQuote(s,'secured',100,b.id));});
check('secured value limit and Level 4 gate reject before spending',()=>{const s=start('expansion'),b=G.purchaseBase(s,'field_hq','command');mission(s,true);next(s);const before=snapshot(s);assert.throws(()=>G.borrow(s,'secured',2200,'command',b.id),/2100/);assert.equal(snapshot(s),before);s.guildLevel=3;assert.throws(()=>G.borrow(s,'secured',100,'command',b.id),/Level 4/);});


check('financing UI shows terms, accepts funded loan, and supports routine repayment',()=>{const elements={},handlers={};function el(id){return elements[id]||(elements[id]={id,innerHTML:'',textContent:'',value:'',open:false,classList:{toggle(){}},addEventListener(){},showModal(){this.open=true},close(){this.open=false}});}const document={getElementById:el,querySelector(){return el('query')},querySelectorAll(){return []},addEventListener(t,fn){handlers[t]=fn}},s=financed(),box={window:{GuildGame:G},document,localStorage:{getItem(){return snapshot(s)},setItem(){}},navigator:{},setTimeout,console};vm.createContext(box);vm.runInContext(fs.readFileSync('./dist/app.js','utf8'),box);function click(dataset){handlers.click({target:{closest:()=>({dataset,disabled:false})}});}click({do:'details',id:s.board.find(c=>c.status==='Offer').id});assert(el('modal-content').innerHTML.includes('Base client cash 900'));click({do:'close'});assert(el('workspace').innerHTML.includes('Guild financing'));assert(el('workspace').innerHTML.includes('900'));click({do:'loan-dialog',type:'unsecured'});el('loan-amount').value='1200';handlers.input({target:{id:'loan-amount'}});assert(el('loan-preview').textContent.includes('100 principal + 24 interest'));click({do:'loan-confirm',type:'unsecured'});const l=box.window.GuildPlaytest.getState().loans[0];assert(l);assert(el('workspace').innerHTML.includes(l.id));click({do:'repay-dialog',id:l.id});el('repay-amount').value='200';click({do:'repay-confirm',id:l.id});assert.equal(box.window.GuildPlaytest.getState().loans[0].remaining,1000);});


check('approved paired economy quotes 900 receipt, 440 wages and employment-related rates',()=>{const s=start('staffed'),c=s.board[0],ids=team(s),q=G.quote(s,c,ids,leads(s,c,ids));assert.equal(q.payout,900);assert.equal(q.pay,440);assert.equal(q.repairWage,110);assert.equal(G.forecast(s),365);assert.equal(900-440-G.forecast(s),95);const m={level:1,employment:'retained'};assert.equal(G.assignmentWage(m),90);assert.equal(G.retainer(m),55);assert.deepEqual(['routine','standard','demanding','expert','legendary'].map(k=>G.contractPayout(1,G.V.contracts[k].payout_factor)),[675,900,2160,3150,4500]);assert.equal(G.wage(2),140);assert.equal(G.contractPayout(2),1145);});
check('actual 0.3.6 deployed quote survives new pay baseline and settles its original economics',()=>{const s=JSON.parse(fs.readFileSync('./fixtures/pay-baseline-036.json','utf8')),j=s.jobs[0],before=snapshot(j.quote),cash=s.cash;G.migrate(s);assert.equal(s.rules,'0.3.10');assert.equal(snapshot(j.quote),before);assert.equal(j.quote.payout,600);assert.equal(j.quote.pay,200);assert.equal(s.cash,cash);assert.equal(G.phaseComplication(s,j,1,0).amount,25);j.rolls=j.quote.checks.map(r=>({...r,face:20,degree:3,actualModifier:r.modifier}));G.endActivity(s);assert.equal(s.cash,cash+400);assert.equal(j.result.success,true);const again=snapshot(s);G.migrate(s);assert.equal(snapshot(s),again);});


check('every combination of two successful phases completes ordinary 2-of-3 contracts',()=>{for(const kind of ['standard','demanding','expert','exclusive'])for(let fail=0;fail<3;fail++)for(const bad of [0,1]){const s=start(),c=s.board[0];c.kind=kind;const j=mission(s);j.rolls=j.quote.checks.map((r,p)=>({...r,face:p===fail?1:20,degree:p===fail?bad:2,actualModifier:r.modifier}));G.endActivity(s);assert.equal(j.result.success,true,kind+' phase '+fail);assert.equal(j.result.successfulPhases,2);assert(j.result.completionReason.includes('2 of 3 phases succeeded; 2 required.'));}});
check('Ghost Relay now completes with any two successes, including failed Engagement',()=>{for(let fail=0;fail<3;fail++){const s=start(),c=s.board.find(c=>c.key==='relay'),ids=team(s);G.secure(s,c.id,'command');const j=G.deploy(s,c.id,ids,leads(s,c,ids));j.rolls=j.quote.checks.map((r,p)=>({...r,face:p===fail?5:20,degree:p===fail?1:2,actualModifier:r.modifier}));G.endActivity(s);assert.equal(j.result.success,true);assert.equal(j.result.successfulPhases,2);assert.equal(j.result.essentialMet,true);assert.equal(s.ledger.filter(l=>l.category==='client').length,1);assert(G.completionRule(c).includes('Any 2 of 3 phases must succeed.'));}});
check('UI states count-only completion and displays the successful two-of-three result',()=>{const elements={},handlers={};function el(id){return elements[id]||(elements[id]={id,innerHTML:'',textContent:'',value:'',open:false,classList:{toggle(){}},addEventListener(){},showModal(){this.open=true},close(){this.open=false}});}const document={getElementById:el,querySelector(){return el('query')},querySelectorAll(){return []},addEventListener(t,fn){handlers[t]=fn}},s=start(),c=s.board.find(c=>c.key==='relay'),ids=team(s);const box={window:{GuildGame:G},document,localStorage:{getItem(){return snapshot(s)},setItem(){}},navigator:{},setTimeout,console};vm.createContext(box);vm.runInContext(fs.readFileSync('./dist/app.js','utf8'),box);function click(dataset){handlers.click({target:{closest:()=>({dataset,disabled:false})}});}click({tab:'contracts'});assert(el('workspace').innerHTML.includes('<b>Completion: Any 2 of 3 phases must succeed.</b>'));G.secure(s,c.id,'command');const j=G.deploy(s,c.id,ids,leads(s,c,ids));j.rolls=j.quote.checks.map((r,p)=>({...r,face:10,degree:p===1?1:2,actualModifier:r.modifier}));G.endActivity(s);const saved=JSON.parse(snapshot(s));box.localStorage.getItem=()=>snapshot(saved);vm.runInContext(fs.readFileSync('./dist/app.js','utf8'),box);assert(el('stage-panel').innerHTML.includes('2 of 3 phases succeeded; 2 required.'));assert(!el('stage-panel').innerHTML.includes('Engagement failed'));assert(el('stage-panel').innerHTML.includes('Completed'));});

check('hero reroll consumes one PC point, keeps second result and survives reload without a second fortune',()=>{const s=start(),j=mission(s);G.endActivity(s);G.rollPhase(s);const r=j.rolls[0],original={face:r.face,degree:r.degree},mod=r.actualModifier,dc=r.dc,pool=s.actions;const expected=G.die(s.seed,'mission-hero',j.departure,j.contract.id,0);G.rerollPhase(s,'command');assert.equal(s.officers[0].heroPoints,0);assert.equal(r.face,expected);assert.equal(r.actualModifier,mod);assert.equal(r.dc,dc);assert.equal(r.originalRoll.face,original.face);assert.equal(s.actions,pool);const before=snapshot(s);assert.throws(()=>G.rerollPhase(s,'quarter'),/one Hero Point/);assert.equal(snapshot(s),before);const clone=JSON.parse(before);G.migrate(clone);assert.throws(()=>G.rerollPhase(clone,'quarter'));assert.equal(clone.jobs[0].rolls[0].face,expected);G.acknowledgePhase(s);G.rollPhase(s);const prev=r.degree,expectedMod=j.quote.checks[1].modifier+(prev===0?-2:prev===1?-1:prev===3?1:0);assert.equal(j.rolls[1].actualModifier,expectedMod);});
check('hero reroll can worsen a roll and updates its complication before any money or crew consequences',()=>{const s=start(),j=mission(s);G.endActivity(s);G.rollPhase(s);const r=j.rolls[0];r.face=20;r.degree=3;r.total=20+r.actualModifier;r.complication=null;const cash=s.cash,status=s.mercs.map(m=>m.status);G.rerollPhase(s,'command');assert.equal(r.degree,G.degree(r.face,r.actualModifier,r.dc));assert.deepEqual(r.complication,G.phaseComplication(s,j,0,r.degree));assert.equal(s.cash,cash);assert.deepEqual(s.mercs.map(m=>m.status),status);assert.equal(r.originalRoll.face,20);assert.equal(r.degree,1);assert(r.face<r.originalRoll.face);});
check('hero resource is per PC per table session, capped and never refreshed by Guild Turns',()=>{const s=start();assert(s.officers.every(o=>o.heroPoints===1));G.awardHeroPoint(s,'command');G.awardHeroPoint(s,'command');assert.equal(s.officers[0].heroPoints,3);assert.throws(()=>G.awardHeroPoint(s,'command'));s.officers[1].heroPoints=0;next(s);assert.equal(s.officers[0].heroPoints,3);assert.equal(s.officers[1].heroPoints,0);const pool=s.actions;G.startHeroSession(s);assert(s.officers.every(o=>o.heroPoints===1));assert.equal(s.heroSession,2);assert.equal(s.actions,pool);const j=mission(s);G.endActivity(s);G.rollPhase(s);assert.throws(()=>G.startHeroSession(s));});
check('third mission check can be rerolled before settlement and cannot be rerolled after accepting it',()=>{const s=start(),j=mission(s);G.endActivity(s);G.rollPhase(s);G.acknowledgePhase(s);G.rollPhase(s);G.acknowledgePhase(s);G.rollPhase(s);const cash=s.cash;assert(!j.settled);G.rerollPhase(s,'quarter');assert.equal(s.cash,cash);assert(!j.settled);G.acknowledgePhase(s);assert(j.settled);const before=snapshot(s);assert.throws(()=>G.rerollPhase(s,'field'));assert.equal(snapshot(s),before);});
check('038 pending mission migrates once with points and count-only completion while preserving recorded data',()=>{const s=JSON.parse(fs.readFileSync('./fixtures/hero-migration-038.json','utf8')),j=s.jobs[0],quote=snapshot(j.quote),rolls=snapshot(j.rolls),cash=s.cash;assert.equal(j.contract.essential,1);G.migrate(s);assert.equal(s.rules,'0.3.10');assert.equal(j.contract.essential,undefined);assert.equal(snapshot(j.quote),quote);assert.equal(snapshot(j.rolls),rolls);assert.equal(s.cash,cash);assert(s.officers.every(o=>o.heroPoints===1));const before=snapshot(s);G.migrate(s);assert.equal(snapshot(s),before);G.rerollPhase(s,'command');});
check('automatic Upkeep preserves current service funding ahead of old debts without forgiving arrears',()=>{const s=start('lean'),m=s.mercs[0];m.employment='retained';m.retainerPaidTurn=1;s.arrears.push({id:'old',creditor:'Old wages',amount:200,type:'wages',turn:1});boundary(s);s.cash=355;G.settleUpkeep(s);assert.equal(s.cash,0);assert.equal(m.retainerPaidTurn,2);assert.equal(s.arrears.find(a=>a.id==='old').amount,200);G.finishUpkeep(s);assert(G.quote(s,s.board[0],team(s),leads(s,s.board[0],team(s))));});
check('discovery tables have complete d20 ranges, bounded levels and correct quality by degree',()=>{for(const key of ['level_offsets','difficulty','rarity'])for(const rows of G.V.discovery[key]){assert.equal(rows.at(-1)[0],20);assert(rows.every((r,i)=>r[0]>=(i?rows[i-1][0]+1:1)));}for(let d=0;d<4;d++)for(let x=1;x<=20;x++){const e=G.discoveryEntry(d,3,{level:x,difficulty:x,rarity:x},5);assert(e.level>=1&&e.level<=5);if(d===0){assert.equal(e.level,2);assert.equal(e.kind,'routine');assert.equal(e.rarity,'Common');}if(d===1)assert.equal(e.rarity,'Common');}assert.equal(G.discoveryEntry(3,3,{level:20,difficulty:20,rarity:20},5).level,5);assert.equal(G.discoveryEntry(3,3,{level:20,difficulty:20,rarity:20},5).kind,'legendary');assert.equal(G.discoveryEntry(3,3,{level:20,difficulty:20,rarity:20},5).rarity,'Rare');});
check('seeded discovery samples every degree, critical quantity branch and rare quality with exactly three otherwise',()=>{const degrees=new Set(),quantities=new Set(),rarities=new Set(),kinds=new Set();for(let seed=0;seed<300;seed++)for(const mode of ['recruits','contracts']){const s=start('developing',seed),cash=s.cash,pool=s.actions;const count=G.network(s,'command',mode,3),d=s.lastRoll.degree;degrees.add(d);if(d===0){quantities.add(count);assert.equal(count,s.lastDiscovery.countRoll<=10?0:1);}else assert.equal(count,3);assert.equal(s.actions,pool-1);assert.equal(s.cash,cash);for(const x of s.lastDiscovery.results){rarities.add(x.rarity);assert(x.level>=1&&x.level<=5);assert(x.rolls.level>=1&&x.rolls.level<=20);if(mode==='contracts'){kinds.add(x.kind);assert.equal(G.offer(s,x.id).status,'Offer');}else{const m=G.merc(s,x.id);assert.equal(m.status,'Candidate');assert.equal(m.expires,2);assert.equal(Object.keys(m.skills).length,x.rarity==='Common'?4:5);}}const reload=JSON.parse(snapshot(s));G.migrate(reload);assert.deepEqual(reload.lastDiscovery,s.lastDiscovery);}assert.equal(degrees.size,4);assert.deepEqual([...quantities].sort(),[0,1]);assert(rarities.has('Rare'));assert(kinds.has('legendary'));});
check('Recruitment Pipeline improves one level once; funded office improves quality without increasing count',()=>{const a=start('expansion'),b=JSON.parse(snapshot(a));a.guildFeats.push('pipeline');G.network(a,'command','recruits',3);G.network(b,'command','recruits',3);if(a.lastRoll.degree>0){assert.equal(a.lastDiscovery.results[0].level,Math.min(9,b.lastDiscovery.results[0].level+1));assert(a.pipelineUsed);}const c=start('expansion');c.facilities.push({id:'office',type:'recruitment_office',baseId:'hq',condition:'Operational',staff:{active:true,paidTurn:1}});G.network(c,'command','recruits',1);assert.equal(c.lastDiscovery.results.length,3);assert(c.lastDiscovery.results.some(x=>x.notes.includes('Recruitment Office specialist')));});
check('UI exposes reroll provenance, session points, discovery dice and removes required-phase wording',()=>{const elements={},handlers={};function el(id){return elements[id]||(elements[id]={id,innerHTML:'',textContent:'',value:'',open:false,classList:{toggle(){}},addEventListener(){},showModal(){this.open=true},close(){this.open=false}});}const document={getElementById:el,querySelector(){return el('query')},querySelectorAll(){return []},addEventListener(t,fn){handlers[t]=fn}},s=start(),j=mission(s),box={window:{GuildGame:G},document,localStorage:{getItem(){return snapshot(s)},setItem(){}},navigator:{},setTimeout,console};vm.createContext(box);vm.runInContext(fs.readFileSync('./dist/app.js','utf8'),box);function click(dataset){handlers.click({target:{closest:()=>({dataset,disabled:false})}});}assert(el('workspace').innerHTML.includes('Player Hero Points'));click({do:'network-contracts'});assert(el('modal-content').innerHTML.includes('Critical Failure'));assert(!el('modal-content').innerHTML.includes('search-difficulty'));el('search-level').value='1';click({do:'network-confirm',mode:'contracts'});assert(el('roll-results').innerHTML.includes('LAST NETWORK DISCOVERY'));assert(el('roll-results').innerHTML.includes('rarity d20'));click({do:'end-confirm'});click({do:'roll'});assert(el('stage-panel').innerHTML.includes('hero-payer'));el('hero-payer').value='command';click({do:'hero-reroll'});assert(el('stage-panel').innerHTML.includes('original d20'));assert(el('stage-panel').innerHTML.includes('Second result kept'));assert.equal(box.window.GuildPlaytest.getState().officers[0].heroPoints,0);assert(!el('stage-panel').innerHTML.includes('Engagement must succeed'));});


check('partial routine arrears payments retain cash and creditor balances without an action',()=>{const s=start();s.arrears.push({id:'owed',creditor:'Old invoice',amount:200,type:'wages',turn:0});const cash=s.cash,pool=s.actions;G.payArrears(s,50);assert.equal(s.cash,cash-50);assert.equal(s.arrears[0].amount,150);assert.equal(s.actions,pool);const before=snapshot(s);assert.throws(()=>G.payArrears(s,0));assert.equal(snapshot(s),before);});

check('relative Guild threat scales from mission and guild levels with explicit complexity',()=>{const s=start();assert.deepEqual([1,2,3,4,5].map(level=>{s.guildLevel=level;return G.contractThreat(s,s.board[0]).label}),['Moderate','Low','Low','Trivial','Trivial']);s.guildLevel=1;assert.deepEqual(['routine','standard','demanding','expert','legendary','exclusive'].map(kind=>G.contractThreat(s,{level:1,kind}).xp),[60,80,120,160,160,120]);assert.equal(G.contractThreat(s,{level:20,kind:'legendary'}).xp,160);assert.equal(G.V.guild_xp_per_level,1000);});
check('Trivial completion retains cash, operative XP, success count and printed DCs',()=>{const s=start();s.guildLevel=5;s.actions=8;const j=mission(s,true);assert.equal(j.quote.guildAward.xp,0);assert.equal(j.quote.payout,900);assert.equal(j.quote.checks[0].dc,15);const cash=s.cash;G.endActivity(s);assert(j.result.success);assert.equal(j.result.guildXP,0);assert.equal(s.pendingGuildXP,0);assert.equal(s.cash,cash+460);assert(s.mercs.every(m=>m.xp===250));assert.equal(j.result.requiredSuccesses,2);});
check('deployment freezes organizational XP independent of later Guild Level or crew oversize',()=>{const s=start(),j=mission(s,true);assert.equal(j.quote.guildAward.xp,80);s.guildLevel=5;G.endActivity(s);assert.equal(j.result.guildXP,80);assert.equal(j.quote.guildAward.guildLevel,1);const a=start('expansion'),c=a.board[0],ids=team(a);const first=G.quote(a,c,ids,leads(a,c,ids));a.mercs.forEach(m=>m.level=7);assert.deepEqual(G.quote(a,c,ids,leads(a,c,ids)).guildAward,first.guildAward);});
check('actual 039 pending save preserves cash, XP, quotes, rolls and Hero Points through idempotent migration',()=>{const s=JSON.parse(fs.readFileSync('./fixtures/progression-039.json','utf8')),j=s.jobs[0],before={cash:s.cash,xp:s.guildXP,pending:s.pendingGuildXP,quote:snapshot(j.quote),roll:snapshot(j.rolls),heroes:snapshot(G.heroPCs(s).map(o=>o.heroPoints))};G.migrate(s);assert.equal(s.rules,'0.3.10');assert.equal(s.cash,before.cash);assert.equal(s.guildXP,before.xp);assert.equal(s.pendingGuildXP,before.pending);assert.equal(snapshot(j.quote),before.quote);assert.equal(snapshot(j.rolls),before.roll);assert.equal(snapshot(G.heroPCs(s).map(o=>o.heroPoints)),before.heroes);assert(s.developmentMilestones.facilities.includes('training_suite'));const again=snapshot(s);G.migrate(s);assert.equal(snapshot(s),again);G.acknowledgePhase(s);j.rolls=j.quote.checks.map(r=>({...r,degree:3,face:20,actualModifier:r.modifier}));// Settlement is driven by final acknowledgement below.
s.operations.pendingReview={job:j.id,phase:2};G.acknowledgePhase(s);assert.equal(j.result.guildXP,250);});
check('first funded owned HQ awards80 once; other owned HQs and return trips do not repeat',()=>{const s=start('expansion');s.cash=100000;const a=G.purchaseBase(s,'field_hq','command'),b=G.purchaseBase(s,'permanent_hq','command');next(s);assert.equal(s.pendingGuildXP,0);G.relocate(s,a.id,'command');assert.equal(s.pendingGuildXP,80);next(s);assert.equal(s.guildXP,80);G.relocate(s,b.id,'command');assert.equal(s.pendingGuildXP,0);next(s);G.relocate(s,a.id,'command');assert.equal(s.pendingGuildXP,0);});
check('outpost milestone requires fully funded property and chief and does not repeat',()=>{const s=start('expansion'),a=G.purchaseBase(s,'outpost','command');G.appointChief(s,a.id,'command');boundary(s);const chief=s.upkeep.invoice.find(l=>l.type==='chief');G.payInvoiceLine(s,chief.id);assert.equal(s.pendingGuildXP,0);G.payInvoiceLine(s,s.upkeep.invoice.find(l=>l.type==='base'&&l.reference===a.id).id);assert.equal(s.pendingGuildXP,80);open(s);assert.equal(s.pendingGuildXP,80);next(s);assert.equal(s.pendingGuildXP,0);});
check('installation milestones wait for funded operation and count one category across all bases',()=>{const s=start('expansion');G.project(s,'recruitment_office','quarter');boundary(s);const f=s.facilities[0];assert.equal(s.pendingGuildXP,0);G.renewStaff(s,f.id,false);open(s);assert.equal(s.pendingGuildXP,0);boundary(s);G.renewStaff(s,f.id,true);open(s);assert.equal(s.pendingGuildXP,30);G.claimMilestones(s);assert.equal(s.pendingGuildXP,30);const other={...JSON.parse(snapshot(f)),id:'copy',baseId:'hq'};s.facilities.push(other);G.claimMilestones(s);assert.equal(s.pendingGuildXP,30);});
check('inherited staffed suite is an established category and earns no retroactive XP',()=>{const s=start('staffed');assert(s.developmentMilestones.facilities.includes('training_suite'));assert.equal(s.pendingGuildXP,0);G.claimMilestones(s);assert.equal(s.pendingGuildXP,0);});
check('HQ relocation preserves Missing, Captured and Dead while moving only Available workers',()=>{const s=start('expansion'),b=G.purchaseBase(s,'field_hq','command');next(s);for(const [i,status]of ['Missing','Captured','Dead'].entries())s.mercs[i].status=status;G.relocate(s,b.id,'command');assert.deepEqual(s.mercs.slice(0,3).map(m=>[m.status,m.baseId]),[['Missing','hq'],['Captured','hq'],['Dead','hq']]);assert.equal(s.mercs[3].status,'In Transit');next(s);assert.deepEqual(s.mercs.slice(0,3).map(m=>m.status),['Missing','Captured','Dead']);assert.equal(s.mercs[3].status,'Available');});
function standingStart(){const s=G.fresh(7,false,4,'lean');s.guildLevel=7;s.guildFeats=['trusted','standing'];open(s);return s;}
check('Standing and Trusted share one free acquisition regardless of order',()=>{for(const order of ['trusted-first','standing-first']){const s=standingStart(),standing=s.board.find(c=>c.standing),ordinary=s.board[0],pool=s.actions;if(order==='trusted-first'){G.secure(s,ordinary.id,'command',true);G.secure(s,standing.id,'command');}else{G.secure(s,standing.id,'command');assert.throws(()=>G.secure(s,ordinary.id,'command',true));G.secure(s,ordinary.id,'command');}assert.equal(s.actions,pool-1);assert(s.trustedUsed);}});
check('prior-turn Standing cards consume the same current-turn allowance',()=>{const s=standingStart(),old=s.board.find(c=>c.standing);next(s);const fresh=s.board.find(c=>c.standing&&c.id!==old.id),pool=s.actions;G.secure(s,old.id,'command');G.secure(s,fresh.id,'command');assert.equal(s.actions,pool-1);});
check('PC administrative benchmark advances transparently while trained skill eligibility stays real',()=>{const s=start();s.guildLevel=10;s.actions=13;const o=G.officer(s,'command');assert.equal(o.skills.Diplomacy,10);G.promote(s,o.id);assert.equal(s.lastRoll.modifier,34);assert.equal(s.lastRoll.dc,39);const before=snapshot(s);assert.throws(()=>G.promote(s,'quarter'));assert.equal(snapshot(s),before);assert.equal(G.officerSkill(s,G.officer(s,'field'),'Computers'),2);});
check('Sector Campaign spends two shared actions and100 cash, replaces promotion and grants no XP',()=>{const s=start('expansion'),cash=s.cash,pool=s.actions,rep=s.reputation;G.sectorCampaign(s,'command');assert.equal(s.cash,cash-100);assert.equal(s.actions,pool-2);assert.equal(s.officers[0].used,2);assert.equal(s.reputation,rep+[-2,0,5,8][s.lastRoll.degree]);assert.equal(s.pendingGuildXP,0);const before=snapshot(s);assert.throws(()=>G.sectorCampaign(s,'command'));assert.throws(()=>G.promote(s,'quarter'));assert.equal(snapshot(s),before);const a=start('expansion');G.promote(a,'command');assert.throws(()=>G.sectorCampaign(a,'command'));});
check('advanced role, level, budget and funding rejections do not mutate state',()=>{for(const setup of [s=>{},s=>{s.guildLevel=4;s.actions=7;},s=>{s.guildLevel=4;s.actions=1;},s=>{s.guildLevel=4;s.actions=7;s.cash=0;}]){const s=start();setup(s);const before=snapshot(s);assert.throws(()=>G.sectorCampaign(s,s.guildLevel===4&&s.actions===7&&s.cash>0?'field':'command'));assert.equal(snapshot(s),before);}});
check('Operations Briefing locks three leads and squad, uses Recon slot and highest circumstance',()=>{let seen=new Set();for(let seed=0;seed<40;seed++){const s=start('expansion',seed),c=s.board[0],ids=team(s),lead=leads(s,c,ids);G.secure(s,c.id,'command');const before=G.quote(s,c,ids,lead),cash=s.cash,pool=s.actions;G.operationsBriefing(s,c.id,ids,lead,'field');seen.add(s.lastRoll.degree);assert.equal(s.cash,cash-100);assert.equal(s.actions,pool-2);const q=G.quote(s,c,ids,lead),bonus=[-1,0,1,2][s.lastRoll.degree];for(let p=0;p<3;p++)assert.equal(q.checks[p].modifier-before.checks[p].modifier,s.lastRoll.degree>=2?bonus:p===1?bonus:0);const stateBefore=snapshot(s);assert.throws(()=>G.recon(s,c.id,'quarter'));assert.throws(()=>G.quote(s,c,ids,[lead[1],lead[0],lead[2]]));assert.equal(snapshot(s),stateBefore);}assert.equal(seen.size,4);});
check('Intensive Training spends two actions and50/person, releases next turn with225 XP and cooldown',()=>{const s=start('staffed');s.guildLevel=6;s.actions=9;const ids=team(s),cash=s.cash,pool=s.actions;G.intensiveTraining(s,ids,'liaison');assert.equal(s.cash,cash-200);assert.equal(s.actions,pool-2);assert(s.mercs.every(m=>m.status==='Training'));next(s);assert(s.mercs.every(m=>m.status==='Available'&&m.xp===225));assert.equal(s.upkeep.choices.length,0);const before=snapshot(s);assert.throws(()=>G.intensiveTraining(s,ids,'liaison'));assert.equal(snapshot(s),before);next(s);assert.throws(()=>G.intensiveTraining(s,ids,'liaison'));next(s);G.intensiveTraining(s,ids,'liaison');});
check('Intensive Training cannot exceed supplied suite capacity or run without funded instructor',()=>{const s=start('staffed');s.guildLevel=6;s.actions=9;G.train(s,team(s),'liaison');for(let i=0;i<3;i++)s.mercs.push({...JSON.parse(snapshot(s.mercs[0])),id:'extra'+i,status:'Available'});const before=snapshot(s);assert.throws(()=>G.intensiveTraining(s,['extra0','extra1','extra2'],'liaison'));assert.equal(snapshot(s),before);const a=start();a.guildLevel=6;a.actions=9;assert.throws(()=>G.intensiveTraining(a,team(a),'liaison'));});
function contingencyFixture(degreeWanted){for(let seed=0;seed<100;seed++){const s=start('expansion',seed),c=s.board.find(c=>c.kind==='demanding'),ids=team(s),lead=leads(s,c,ids);G.secure(s,c.id,'command');G.extractionContingency(s,c.id,ids,lead,'field');if(s.lastRoll.degree===degreeWanted){const j=G.deploy(s,c.id,ids,lead);j.rolls=j.quote.checks.map(r=>({...r,face:5,degree:1,actualModifier:r.modifier}));return {s,j};}}throw Error('No fixture roll');}
check('one contingency charge protects Missing before repairs without changing failed outcome',()=>{const {s,j}=contingencyFixture(2),cash=s.cash;G.endActivity(s);assert.equal(j.result.success,false);assert.equal(j.result.contingencyUsed,1);assert.equal(G.merc(s,j.leads[2]).status,'Recovering');assert.equal(s.cash,cash-G.wage(3));assert.equal(j.result.complications.find(c=>c.phase===2).recovery,1);});
check('two contingency charges protect Missing and halve repairs with printed recovery preserved',()=>{const {s,j}=contingencyFixture(3),cash=s.cash;G.endActivity(s);assert.equal(j.result.contingencyUsed,2);assert.equal(s.cash,cash-Math.ceil(G.wage(3)/2));assert.equal(G.merc(s,j.leads[2]).status,'Recovering');assert.equal(j.result.guildXP,undefined);});
check('contingency costs scale with frozen wages and cannot be repeated or retargeted',()=>{const {s,j}=contingencyFixture(2),h=s.actionHistory.find(h=>h.action==='Establish an Extraction Contingency');assert.equal(h.cost,3);assert.equal(h.credits,5*Math.ceil(j.quote.pay*.25/5));const other=s.board.find(c=>c.status==='Offer');G.secure(s,other.id,'command');const before=snapshot(s);assert.throws(()=>G.extractionContingency(s,other.id,team(s),[],'field'));assert.equal(snapshot(s),before);});
check('three final critical successes show discretionary guidance without automatic Hero Points or extra payout',()=>{for(const trivial of [false,true]){const s=start();if(trivial){s.guildLevel=5;s.actions=8;}const points=snapshot(G.heroPCs(s).map(o=>o.heroPoints)),j=mission(s,true),cash=s.cash;G.endActivity(s);assert(j.result.exceptionalPerformance);assert.equal(s.cash,cash+460);assert.equal(j.result.guildXP,trivial?0:80);assert.equal(snapshot(G.heroPCs(s).map(o=>o.heroPoints)),points);assert(j.result.exceptionalGuidance.includes(trivial?'does not normally merit':'GM may award one'));}});
