check('morale and recovery limits apply to target per turn without personal officer caps',()=>{const s=start(),ids=team(s);G.morale(s,ids.slice(0,2),'command');const before=snapshot(s);assert.throws(()=>G.morale(s,ids,'quarter'));assert.equal(snapshot(s),before);G.morale(s,ids.slice(2),'quarter');s.mercs[0].status='Recovering';s.mercs[0].readyAt=10;G.recover(s,[ids[0]],'liaison');const after=snapshot(s);assert.throws(()=>G.recover(s,[ids[0]],'quarter'));assert.equal(snapshot(s),after);});

function uiFixture(s){const elements={},handlers={};function el(id){return elements[id]||(elements[id]={id,innerHTML:'',textContent:'',value:'',open:false,className:'',classList:{toggle(){}},addEventListener(){},showModal(){this.open=true},close(){this.open=false}});}const document={getElementById:el,querySelector(selector){return el(selector)},querySelectorAll(selector){if(selector.includes('input[name="crew"]'))return [...el('modal-content').innerHTML.matchAll(/<input type="checkbox" name="crew" value="([^"]+)" ([^>]*)>/g)].filter(m=>m[2].includes('checked')).map(m=>({value:m[1]}));return [];},addEventListener(t,fn){handlers[t]=fn}},box={window:{GuildGame:G},document,localStorage:{getItem(){return snapshot(s)},setItem(){}},navigator:{},setTimeout,console};vm.createContext(box);vm.runInContext(fs.readFileSync('./dist/app.js','utf8'),box);function click(dataset){handlers.click({target:{closest:()=>({dataset,disabled:false})}});}function officer(id){el('active-officer').value=id;handlers.change({target:{id:'active-officer',value:id,matches(){return false}}});}return {box,el,click,officer};}
check('UI shows relative threat XP, milestone status and multi-action menus with exact plan quote',()=>{const s=start('expansion'),c=s.board[0];G.secure(s,c.id,'command');const u=uiFixture(s);assert(u.el('workspace').innerHTML.includes('Sector Campaign'));assert(u.el('workspace').innerHTML.includes('first funded'));u.officer('field');u.click({tab:'contracts'});assert(u.el('workspace').innerHTML.includes('Low for Guild Level 4'));assert(u.el('workspace').innerHTML.includes('Operations Briefing'));u.click({do:'briefing',id:c.id});assert(u.el('modal-content').innerHTML.includes('plan-confirm'));assert(u.el('deployment-quote').innerHTML.includes('Plan price: 100 credits'));const before=u.box.window.GuildPlaytest.getState();u.click({do:'plan-confirm',mode:'briefing',id:c.id});const after=u.box.window.GuildPlaytest.getState();assert.equal(after.cash,before.cash-100);assert.equal(after.actions,before.actions-2);assert(G.offer(after,c.id).preparation.lock);u.click({do:'deploy',id:c.id});u.click({do:'deploy-confirm',id:c.id});assert.equal(u.box.window.GuildPlaytest.getState().jobs.length,1);});
check('UI funds a wage-scaled contingency and deploys its locked assignment',()=>{const s=start('expansion'),c=s.board.find(c=>c.kind==='demanding');G.secure(s,c.id,'command');const u=uiFixture(s);u.officer('field');u.click({do:'contingency',id:c.id});assert(u.el('deployment-quote').innerHTML.includes('Plan price: 170 credits'));const before=u.box.window.GuildPlaytest.getState();u.click({do:'plan-confirm',mode:'contingency',id:c.id});const after=u.box.window.GuildPlaytest.getState();assert.equal(after.cash,before.cash-170);assert.equal(after.actions,before.actions-3);assert(G.offer(after,c.id).contingency.lock);u.click({do:'deploy',id:c.id});u.click({do:'deploy-confirm',id:c.id});assert.equal(u.box.window.GuildPlaytest.getState().jobs.length,1);});
check('UI intensive training needs no admin roll to complete its confirmation flow',()=>{const s=start('staffed');s.guildLevel=6;s.actions=9;const u=uiFixture(s);u.officer('liaison');u.click({do:'intensive'});assert(u.el('personnel-cost').textContent.includes('225 XP'));u.click({do:'personnel-confirm',mode:'intensive'});assert(u.el('notice').textContent.includes('Intensive training funded'));assert.equal(u.box.window.GuildPlaytest.getState().actions,7);});
check('UI retains exceptional-performance guidance and actual XP in settled results',()=>{const s=start(),j=mission(s,true);G.endActivity(s);const u=uiFixture(s);assert(u.el('stage-panel').innerHTML.includes('GM may award one Hero Point'));assert(u.el('stage-panel').innerHTML.includes('Guild XP: 80'));assert(u.el('stage-panel').innerHTML.includes('Extraction'));assert.equal(u.box.window.GuildPlaytest.getState().officers[0].heroPoints,1);});

